words = np.array([[B, A, K, E],
                  [O, N, Y, X],
                  [E, C, H, O],
                  [O, V, A, L],
                  [G, I, R, D],
                  [S, M, U, G],
                  [J, U, M, P],
                  [T, O, R, N],
                  [L, U, C, K],
                  [V, I, N, Y],
                  [L, U, S, H],
                  [W, R, A, P]])

dice = intvar(0, n - 1, shape=m, name="dice")

model = Model()

# the letters in a word must be on a different die
for word in range(num_words):
    # Also, adjust for 1-based
    model += (AllDifferent([dice[words[word] - 1]]))

